+const path = require('path')
+const fs = require('fs-extra')
+const rimraf = require('rimraf')
+
+const base = path.join(__dirname, 'src/recipes/providers/gatsby')
+const shadowFile = require(path.join(base, 'shadow-file'))
+const plugin = require(path.join(base, 'plugin'))
+
+const sfRoot = path.join(base, 'fixtures')
+const blogRoot = path.join(base, 'fixtures/gatsby-starter-blog')
+const helloRoot = path.join(base, 'fixtures/gatsby-starter-hello-world')
+
+async function main() {
+  rimraf.sync(path.join(sfRoot, 'src'))
+
+  // ---- ShadowFile ----
+  const ctx = { root: sfRoot }
+  const initial = { theme: 'gatsby-theme-blog', path: 'src/components/author.js' }
+  const createPlan = await shadowFile.plan(ctx, initial)
+  console.log('SF create plan id:', createPlan.id, '| path:', createPlan.path, '| currentState:', JSON.stringify(createPlan.currentState))
+  const createRes = await shadowFile.create(ctx, initial)
+  console.log('SF create:', JSON.stringify({ ...createRes, contents: createRes.contents.slice(0,20)+'...' }))
+  const readRes = await shadowFile.read(ctx, createRes.id)
+  const eq = JSON.stringify(readRes) === JSON.stringify(createRes)
+  console.log('SF read equals create:', eq)
+  const updated = { ...readRes, ...{ theme: 'gatsby-theme-blog', path: 'src/components/author.js' } }
+  const updatePlan = await shadowFile.plan(ctx, updated)
+  console.log('SF update plan diff:', JSON.stringify(updatePlan.diff).slice(0,60))
+  const updateRes = await shadowFile.update(ctx, updated)
+  const destroyRes = await shadowFile.destroy(ctx, updateRes)
+  console.log('SF destroy id:', destroyRes.id)
+  const postRead = await shadowFile.read(ctx, createRes.id)
+  console.log('SF post-destroy read undefined:', postRead === undefined)
+  rimraf.sync(path.join(sfRoot, 'src'))
+
+  // ---- Plugin hello-world ----
+  const hctx = { root: helloRoot }
+  const cfgBefore = await fs.readFile(path.join(helloRoot, 'gatsby-config.js'), 'utf8')
+  const name = 'gatsby-plugin-foo'
+  const pcreatePlan = await plugin.plan(hctx, { id: name, name })
+  console.log('PLUGIN hello create plan id:', pcreatePlan.id)
+  const pcreate = await plugin.create(hctx, { id: name, name })
+  console.log('PLUGIN hello create:', JSON.stringify(pcreate))
+  const pread = await plugin.read(hctx, pcreate.id)
+  console.log('PLUGIN read equals create:', JSON.stringify(pread) === JSON.stringify(pcreate))
+  await plugin.destroy(hctx, { name })
+  const postPRead = await plugin.read(hctx, name)
+  console.log('PLUGIN post-destroy undefined:', postPRead === undefined)
+  // restore hello-world config to original bytes
+  await fs.writeFile(path.join(helloRoot, 'gatsby-config.js'), cfgBefore)
+
+  // ---- Plugin all on blog ----
+  const all = await plugin.all({ root: blogRoot })
+  console.log('PLUGIN all count:', all.length, '| names:', all.map(a=>a.name).join(','))
+  console.log('ALL GOOD')
+}
+main().catch(e => { console.error('ERROR', e); process.exit(1) })
